#!/usr/bin/env python3
"""A local, source-backed atlas of the 021 layout study and real engine views."""
from pathlib import Path
import html,json,math,sys
import numpy as np
sys.dont_write_bytecode=True
from visual_006_audit import GLB
ROOT=Path(__file__).resolve().parents[2];LIB=ROOT/'docs/design/map-layout-021'
def read(p):return json.loads(Path(p).read_text())
def esc(v):return html.escape(str(v),quote=True)
def logical(v):
    v=v/np.linalg.norm(v,axis=-1,keepdims=True)
    return np.column_stack((2048+np.arctan2(v[:,0],v[:,2])*6144/math.tau,681.5-np.arcsin(v[:,1])*2400/math.pi))
def main():
    p=read(LIB/'placements.json');nodes=read(ROOT/'data/rulesets/lshu_configurable_v1/board_nodes.json')['items']
    cats={k:{a['id']:a for a in read(ROOT/f'docs/design/{v}/catalog.json')['assets']} for k,v in [('terrain','terrain-library-018'),('landmark','landmark-library-020'),('city','city-library-019')]}
    svg=[]
    for primitive in GLB(ROOT/'assets/game/lowpoly/planet/terrain.glb').primitives():
        if primitive['name']!='spherical_continents_and_biomes':continue
        xy=logical(primitive['positions']);color=primitive.get('color')
        for face in primitive['faces']:
            pts=xy[face]
            if np.ptp(pts[:,0])>500 or pts[:,0].max()<0 or pts[:,0].min()>4360:continue
            rgb=np.mean(color[face,:3],axis=0) if color is not None else np.array([.45,.48,.25])
            rgb=np.where(rgb<=.0031308,rgb*12.92,1.055*rgb**(1/2.4)-.055)
            fill='#'+''.join(f'{round(float(np.clip(c,0,1))*255):02x}' for c in rgb)
            svg.append('<path d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'Z" fill="'+fill+'"/>')
    for edge in read(ROOT/'data/rulesets/lshu_configurable_v1/board_edges.json')['items']:
        points=' '.join(f'{a[0]:.1f},{a[1]:.1f}' for a in edge['movement_polyline'])
        svg.append(f'<polyline points="{points}" fill="none" stroke="'+('#f8eac5' if edge['route_type']=='LAND' else '#acd8e9')+'" stroke-width="8" stroke-linecap="round"/>')
    for a in p['props']:
        x,y=a['logical']
        if 0<=x<=4360 and -160<=y<=1410:
            svg.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="8" fill="#37654a" opacity=".7"/>')
    cities={n['id']:n for n in nodes if n['node_type']=='CITY'}
    for cid,n in cities.items():
        x,y=n['map_position'];y-=85
        svg.append(f'<g class="citymark" data-city="{cid}"><circle cx="{x}" cy="{y}" r="19" fill="#a64d39" stroke="#fff4d6" stroke-width="4"/><text x="{x}" y="{y+59}" text-anchor="middle" font-size="36" fill="#fff5d8" stroke="#4b4c3e" stroke-width="7" paint-order="stroke">{esc(cats["city"][cid]["name"])}</text></g>')
    assets=[]
    for i,a in enumerate(p['landmarks'],1):
        m=cats['landmark'][a['asset_id']];x,y=a['logical'];r=a['footprint_radius']/(11*math.pi/2400)
        dash='stroke-dasharray="10 8"' if a.get('requires_land_extension') else ''
        svg.append(f'<g class="landmarkmark" data-landmark="{a["id"]}" tabindex="0" role="button" aria-label="{esc(m["name"])}"><title>{esc(m["name"])} · {esc(m["city"])}</title><circle cx="{x:.1f}" cy="{y:.1f}" r="{r:.1f}" fill="#f6de9b" fill-opacity=".18" stroke="#744e20" stroke-width="4" {dash}/><circle cx="{x:.1f}" cy="{y:.1f}" r="22" fill="#efcb79"/><text x="{x:.1f}" y="{y+10:.1f}" text-anchor="middle" font-size="28" font-weight="600" fill="#45351d">{i}</text></g>')
        assets.append({'id':a['id'],'number':i,'name':m['name'],'city':m['city'],'city_id':m['city_id'],'scope':m['scope_label'],'direction':m['direction_note'],'note':a.get('layout_note',a.get('orientation_intent','')),'reserved':a.get('requires_land_extension',False),'logical':a['logical'],'thumb':'../landmark-library-020/previews/'+a['asset_id']+'-three-quarter.jpg'})
    options=''.join(f'<option value="{v["id"]}">{esc(v["title"])}</option>' for v in p['views'])
    list_html=''.join(f'<button data-asset="{a["id"]}" class="asset"><span class="num">{a["number"]:02d}</span><span>{esc(a["name"])}<small>{esc(a["city"])}'+(' · 岸形预留' if a['reserved'] else '')+'</small></span></button>' for a in assets)
    document='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>丝路星球 · 地图布局方案 021</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#344438;background:#f4f1e9;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,select,a{font:inherit;color:inherit}button,select{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #a27132;outline-offset:3px}header,main,footer{max-width:1420px;margin:auto;padding:0 36px}header{padding-top:44px;padding-bottom:24px}.eyebrow{font-size:11px;letter-spacing:.15em;color:#7c856c}h1{font-size:clamp(30px,4vw,46px);font-weight:550;margin:15px 0 13px}p{line-height:1.85}header p{max-width:870px;font-size:14px;color:#77806e;margin:0}.stats{display:flex;gap:26px;font-size:12px;margin-top:22px}.stats b{font-size:22px;font-weight:500;margin-right:5px}.notice{font-size:12px;line-height:1.9;padding:14px 18px;background:#e7eadb;border-left:3px solid #849870;border-radius:4px;margin:0 0 25px}.controls{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:16px 0}select,.switch{border:1px solid #cbd1bf;border-radius:5px;background:#faf9f3;padding:9px 13px;font-size:13px}.switch{display:flex;gap:3px;padding:3px}.switch button{border:0;background:none;border-radius:3px;font-size:12px;padding:8px 14px}.switch button[aria-pressed="true"]{background:#dde5d2}.viewer{position:relative;background:#152d46;border-radius:7px;overflow:hidden}.viewer img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain}.caption{color:#808573;font-size:12px;line-height:1.8;margin:11px 0 27px}.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;border-top:1px solid #d5dacb;border-bottom:1px solid #d5dacb;padding:22px 0;margin-bottom:30px}.principles h2{font-size:16px;font-weight:550;margin:0 0 9px}.principles p{font-size:12px;color:#77816e;margin:0}.atlas-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px}h2{font-size:23px;font-weight:550}.atlas-head span{font-size:12px;color:#7c8572}.atlas{background:#78a4ad;border:1px solid #c1cbc1;border-radius:6px;overflow:hidden}.atlas svg{display:block;width:100%;height:auto}.landmarkmark,.citymark{cursor:pointer}.landmarkmark:hover circle{stroke:#fff9df;stroke-width:7}.legend{font-size:12px;line-height:1.8;color:#7a846f;margin:10px 0 24px}.details{display:grid;grid-template-columns:1.1fr 1fr;gap:25px}.assetlist{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;max-height:640px;overflow:auto;padding:2px 8px 3px 2px}.asset{display:flex;gap:13px;align-items:center;text-align:left;background:#faf9f3;border:1px solid #e0e2d5;border-radius:4px;padding:13px 12px;font-size:12px}.asset.active{border-color:#82936e;background:#e7eddf}.num{font-size:11px;color:#a08458}small{display:block;font-size:10px;color:#7c836f;margin-top:5px}.detailcard{background:#faf9f3;border:1px solid #dce0d1;border-radius:7px;padding:20px;align-self:start;position:sticky;top:20px}.detailcard img{width:100%;max-height:270px;object-fit:contain;background:#f1ecdc;border-radius:4px}.detailcard h3{font-size:22px;margin:18px 0 6px}.detailcard p{font-size:12px;color:#76816b;margin:8px 0}.detailcard button{background:#dfe6d4;border:1px solid #bccbb0;border-radius:4px;padding:9px 13px;font-size:12px}.tag{display:inline-block;font-size:10px;padding:5px 8px;background:#e6e9dc;border-radius:3px}.tag.reserve{background:#f0e1bf;color:#8f622a}footer{padding-top:34px;padding-bottom:40px;font-size:12px;color:#7c846f;line-height:1.9}footer a{text-underline-offset:4px}.muted{font-size:11px;color:#8b8e7f}.hidden{display:none}@media(max-width:850px){header,main,footer{padding-left:20px;padding-right:20px}.principles{grid-template-columns:1fr;gap:16px}.details{grid-template-columns:1fr}.detailcard{position:static;grid-row:1}.assetlist{max-height:360px}.atlas-head{display:block}.stats{gap:17px;flex-wrap:wrap}.viewer{margin-left:-10px;margin-right:-10px}h2{font-size:21px}}
</style></head><body><header><div class="eyebrow">SILK ROAD / MAP LAYOUT STUDY 021</div><h1>丝路星球 · 地图布局方案</h1><p>先读城市和商道，再读沿途地貌。用已有的城市、地标与基础地形搭出区域层次，让每段旅程有自己的环境特征。</p><div class="stats"><span><b>16</b>城市节点</span><span><b>33</b>地理地标</span><span><b>24</b>基础造型</span><span><b>RESERVES</b>处岸形预留</span></div></header><main><div class="notice">这是可对照的实机布局草案。城市以原尺寸的 82% 试排；规则节点与商道保持原位。虚线标记的地标按地理方位预留，需要后续调整局部岸形。底座与连续地形的融合仍需精修，尚未替换正式地图。</div><div class="controls"><select id="view" aria-label="查看区域或城市">OPTIONS</select><div class="switch" aria-label="布局对照"><button data-phase="baseline" aria-pressed="false">原地图</button><button data-phase="layout" aria-pressed="true">布局草案</button></div></div><div class="viewer"><img id="scene" src="previews/overview-layout.jpg" alt="星球总览 · 布局草案实机画面"></div><p class="caption" id="scene-caption">Godot 实机画面 · 相同镜头与灯光 · 可切换原地图对照。</p><p class="caption"><a id="full-view" href="previews/overview-layout.jpg" target="_blank" rel="noopener">打开原尺寸实拍 ↗</a></p><div class="principles"><div><h2>城市周围留开口</h2><p>正面留给商道、车船与城市入口。矮灌木和岩石分组放在两侧，地标错开城名与主要建筑轮廓。</p></div><div><h2>地标组成区域</h2><p>长城与雅丹形成河西走廊；雪山与荒漠衔接中亚；河谷、湿地、海礁沿南部与沿海展开。每城两件分在不同景深。</p></div><div><h2>疏密之间有过渡</h2><p>疏林接山脚，低植被接城市。命名地标集中在旅途可见区；泛形山丘、极地雪峰和少量云布置在外围。</p></div></div><div class="atlas-head"><h2>地理布置总图</h2><span>点击编号看地标与所属区域，再切换对应城市实拍</span></div><div class="atlas"><svg viewBox="0 -160 4360 1600" xmlns="http://www.w3.org/2000/svg" aria-label="现有大陆、商道与地标规划位置">SVG</svg></div><p class="legend">红点：城市　金圈：地标　虚线圈：需要岸形调整　绿点：低景物与疏林。<br>底图取自当前真实球面地形的展开投影；展示前侧区域，极地与背面布局请切换上方实机机位。</p><div class="details"><div class="assetlist" aria-label="33件地标清单">LIST</div><aside class="detailcard"><img id="thumb" alt=""><h3 id="asset-title"></h3><span id="asset-tag" class="tag"></span><p id="asset-direction"></p><p id="asset-note"></p><button id="focus">查看所属城市实拍</button><p class="muted">单件图是020模型棚拍；上方地图图是021实际摆放。两者用途不同。</p></aside></div></main><footer><a href="README.md">布局决策与接入顺序</a> · <a href="geography-placement-notes.md">逐项地理说明</a> · <a href="composition-notes.md">构图准则</a><br><a href="../terrain-library-018/index.html">基础地形库018</a> · <a href="../city-library-019/index.html">城市精修库019</a> · <a href="../landmark-library-020/index.html">地理景观库020</a><p>独立预览场景支持拖动星球、滚轮缩放、城市聚焦及图层切换；启动方式见制作说明。本页负责对照与地理总览。</p></footer><script>
const assets=ASSETS,views=VIEWS;let phase='layout',selected=assets[0];const scene=document.querySelector('#scene');
function refresh(){const v=views.find(x=>x.id===document.querySelector('#view').value);scene.src='previews/'+v.id+'-'+phase+'.jpg';document.querySelector('#full-view').href=scene.src;scene.alt=v.title+' · '+(phase==='layout'?'布局草案':'原地图')+'实机画面';document.querySelector('#scene-caption').textContent=v.title+' · Godot实机'+(phase==='layout'?'布局草案':'原地图')+' · 缩放 '+v.zoom+' · 相同镜头与灯光';}
function choose(id){selected=assets.find(x=>x.id===id);document.querySelector('#thumb').src=selected.thumb;document.querySelector('#thumb').alt=selected.name+'实际模型棚拍';document.querySelector('#asset-title').textContent=selected.name;const tag=document.querySelector('#asset-tag');tag.textContent=selected.city+' · '+selected.scope+(selected.reserved?' · 岸形预留':'');tag.classList.toggle('reserve',selected.reserved);document.querySelector('#asset-direction').textContent=selected.direction;document.querySelector('#asset-note').textContent=selected.note;document.querySelectorAll('[data-asset]').forEach(b=>b.classList.toggle('active',b.dataset.asset===id));}
document.querySelector('#view').onchange=refresh;document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.phase;document.querySelectorAll('[data-phase]').forEach(x=>x.setAttribute('aria-pressed',x===b));refresh()});document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>choose(b.dataset.asset));document.querySelectorAll('[data-landmark]').forEach(b=>{b.onclick=()=>choose(b.dataset.landmark);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(b.dataset.landmark)}}});document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{document.querySelector('#view').value='city_'+b.dataset.city;refresh();scene.scrollIntoView({behavior:'smooth',block:'center'})});document.querySelector('#focus').onclick=()=>{document.querySelector('#view').value=selected.city_id==='himalaya'?'central':'city_'+selected.city_id;refresh();scene.scrollIntoView({behavior:'smooth',block:'center'})};choose(assets[0].id);refresh();
</script></body></html>'''
    document=document.replace('RESERVES',str(sum(a['reserved'] for a in assets))).replace('OPTIONS',options).replace('SVG',''.join(svg)).replace('LIST',list_html).replace('ASSETS',json.dumps(assets,ensure_ascii=False).replace('</','<\\/')).replace('VIEWS',json.dumps(p['views'],ensure_ascii=False))
    (LIB/'index.html').write_text(document)
    (LIB/'atlas-catalog.json').write_text(json.dumps({'assets':assets,'views':p['views']},ensure_ascii=False,indent=2)+'\n')
    print('021 atlas ready',len(assets),'landmarks',len(svg),'SVG elements')
if __name__=='__main__':main()
